#include "../src/render_plan.hpp"
#include "../src/presentation.hpp"
#include <cassert>
#include <iostream>
int main(){for(auto dims: {rendering::Size{640,480},{1914,1000},{1920,1080},{3840,2160},{735,835}}){auto v=presentation::aspectFit(dims.width,dims.height,0,0);auto frame=presentation::frameFor(v);for(int level=0;level<3;++level){auto foreground=rendering::foreground(v.width,v.height,frame.width,frame.height,false);assert(foreground.width==v.width&&foreground.height==v.height);auto scene=rendering::scenery(foreground,level);assert(scene.width<=foreground.width&&scene.height<=foreground.height);if(level)assert(std::max(scene.width,scene.height)<=(level==1?960:1440));else assert(scene.width==foreground.width&&scene.height==foreground.height);assert(std::abs(scene.width/(double)scene.height-v.width/(double)v.height)<.01);}auto crt=rendering::foreground(v.width,v.height,frame.width,frame.height,true);assert(crt.width==frame.width&&crt.height==frame.height);}assert(rendering::interval(1)==100&&rendering::interval(2)==50);std::cout<<"PASS: full-resolution weather/text independent of animation level; proportional scenery caps, CRT sizing and target intervals.\n";}
